#include <math.h>

void test_nonuniform_position_map(
  double t, const double *GKYL_RESTRICT xn, double *GKYL_RESTRICT fout, void *ctx
)
{
  double poly_order = 2;
  double z = xn[0];
  double left = 0.25;
  double right = 0.75;
  if (z < -left) {
    fout[0] = z;
  } else if (z < right) {
    fout[0] = -pow(z - right, poly_order) / fabs(pow(left - right, poly_order - 1)) + right;
  } else {
    fout[0] = z;
  }
}

void test_nonuniform_position_map_slope(
  double t, const double *GKYL_RESTRICT xn, double *GKYL_RESTRICT fout, void *ctx
)
{
  double poly_order = 2;
  double z = xn[0];
  double left = 0.25;
  double right = 0.75;
  if (z < -left) {
    fout[0] = 1.0;
  } else if (z < right) {
    fout[0] =
      -poly_order * pow(z - right, poly_order - 1) / fabs(pow(left - right, poly_order - 1));
  } else {
    fout[0] = 1.0;
  }
}

void test_identity_position_map(
  double t, const double *GKYL_RESTRICT xn, double *GKYL_RESTRICT fout, void *ctx
)
{
  fout[0] = xn[0];
}

void test_nonuniform_position_map_3x(
  double t, const double *GKYL_RESTRICT xn, double *GKYL_RESTRICT fout, void *ctx
)
{
  double poly_order = 2;
  double left = 0.25;
  double right = 0.75;
  for (int i = 0; i < 3; i++) {
    double z = xn[i];
    if (z < -left) {
      fout[i] = z;
    } else if (z < right) {
      fout[i] = -pow(z - right, poly_order) / fabs(pow(left - right, poly_order - 1)) + right;
    } else {
      fout[i] = z;
    }
  }
}

void bmag_func(double t, const double *GKYL_RESTRICT xn, double *GKYL_RESTRICT fout, void *ctx)
{
  double x = xn[0];
  double s = 0.6;
  double c = 0.;
  // double B = (4*pow(s*(x-c),2) - 0.3*pow(s*(x-c),4) + 1)*exp(-pow(s*(x-c),2));
  double B = 1 / (1 + 100 * pow(x - M_PI / 2, 2)) + 1 / (1 + 100 * pow(x + M_PI / 2, 2));
  fout[0] = B;
}

